async function getSession(env, chatId) {
  const key = `omni_session:${chatId}`;
  const tryGet = async (kv) => { if(!kv) return null; try{ const v=await kv.get(key); if(v){ const j=JSON.parse(v); if(j&&Array.isArray(j.deployments)){ USER_SESSIONS.set(chatId,j); return j; } } }catch{} return null; };
  let r = await tryGet(env.SESSIONS_KV); if(r) return r;
  r = await tryGet(env.OMNI_KV); if(r) return r;
  r = await tryGet(env.SESSIONS); if(r) return r;
  r = await tryGet(env.kv); if(r) return r;
  return USER_SESSIONS.get(chatId) || { step:"idle", deployments:[], activeIndex:0 };
}
async function saveSession(env, chatId, s){ USER_SESSIONS.set(chatId,s); const k=`omni_session:${chatId}`, v=JSON.stringify(s); const put=async(kv)=>{ if(kv) try{ await kv.put(k,v);}catch{} }; await put(env.SESSIONS_KV); await put(env.OMNI_KV); await put(env.SESSIONS); await put(env.kv); }

