function rand(a){ return a[Math.floor(Math.random()*a.length)]; }
function randInt(min,max){ return Math.floor(Math.random()*(max-min+1))+min; }
// Geneva Fragment رندوم برای هر کانفیگ
function genevaFragment(){
  const len = `${randInt(10,30)}-${randInt(40,100)}`;
  const interval = `${randInt(1,5)}-${randInt(10,20)}`;
  const packets = rand(["tlshello","1-1","1-2","1-3"]);
  return { len, interval, packets };
}
// uTLS JA4 رندوم
function utlsFP(){ return rand(UTLS_FPS); }

// تولید 20 کانفیگ 3 لایه (7 Arvan + 7 CF + 6 Warp) با Geneva/ECH/uTLS/XHTTP/gRPC
function generatePhantomConfigs(domain, uuid, opts={}){
  const all = [];
  // v10 note: L1 (Arvan IP + spoofed SNI) & L3 (Warp) are EXPERIMENTAL decoys — TLS
  // terminates on Arvan/CF edge and will NOT reach this worker's VLESS handler.
  // The RELIABLE path is L2 (clean CF IP + SNI = your own worker domain).
  // لایه 1: Arvan 7 تا - WS + XHTTP
  for(let i=0;i<7;i++){
    const sni = WHITELIST_SNI[i%WHITELIST_SNI.length];
    const ip = ARVAN_CLEAN_IPS[i%ARVAN_CLEAN_IPS.length];
    const port = ARVAN_PORTS[i%ARVAN_PORTS.length];
    const frag = genevaFragment();
    const fp = utlsFP();
    const type = i%2===0 ? "ws" : "xhttp"; // Geneva: یکی WS یکی XHTTP
    const path = type==="xhttp" ? "/xhttp?mode=auto" : "/?ed=2048";
    const ech = i%3===0 ? "&ech=true" : ""; // هر 3 تا یکی ECH
    const link = `vless://${uuid}@${ip}:${port}?encryption=none&security=tls&sni=${sni}&fp=${fp}&type=${type}&host=${domain}&path=${encodeURIComponent(path)}${ech}&fragment=${frag.len},${frag.interval},${frag.packets}#${encodeURIComponent(`[L1-Arvan] ${sni}-${type}-${port}`)}`;
    all.push({ tier:"L1-Arvan", sni, ip, port, type, fp, frag, link });
  }
  // لایه 2: CF 7 تا - WS + gRPC + Fragment
  for(let i=0;i<7;i++){
    const sni = domain; // برای CF از خود دامنه یا ECH
    const ip = CF_CLEAN_IPS[i%CF_CLEAN_IPS.length];
    const port = 443;
    const frag = genevaFragment();
    const fp = utlsFP();
    const type = i%3===0 ? "grpc" : "ws";
    const path = type==="grpc" ? "grpc-mode" : "/?ed=2048";
    const link = `vless://${uuid}@${ip}:${port}?encryption=none&security=tls&sni=${sni}&fp=${fp}&type=${type}&host=${domain}&path=${encodeURIComponent(path)}&fragment=${frag.len},${frag.interval},${frag.packets}&allowInsecure=1#${encodeURIComponent(`[L2-CF] ${type}-${ip}`)}`;
    all.push({ tier:"L2-CF", sni, ip, port, type, fp, frag, link });
  }
  // لایه 3: Warp 6 تا - Warp on Warp
  for(let i=0;i<6;i++){
    const ip = WARP_IPS[i%WARP_IPS.length];
    const sni = rand(WHITELIST_SNI);
    const frag = genevaFragment();
    const link = `vless://${uuid}@${ip}:443?encryption=none&security=tls&sni=${sni}&fp=${utlsFP()}&type=ws&host=${domain}&path=${encodeURIComponent("/?ed=2048")}&fragment=${frag.len},${frag.interval},${frag.packets}#${encodeURIComponent(`[L3-Warp] ${sni}`)}`;
    all.push({ tier:"L3-Warp", sni, ip, port:443, type:"ws", frag, link });
  }
  // Shadowsocks2022 + Cloak (برای ShadowRocket)
  const ssKey = btoa(uuid.replace(/-/g,"")).substring(0,32); // کلید نمونه
  const ssLinks = [
    `ss://2022-blake3-aes-128-gcm:${ssKey}@${rand(ARVAN_CLEAN_IPS)}:443#${encodeURIComponent("[SS2022] Arvan-Cloak")}`,
    `ss://2022-blake3-chacha20-poly1305:${ssKey}@${rand(CF_CLEAN_IPS)}:443#${encodeURIComponent("[SS2022] CF-Cloak")}`
  ];
  // Hysteria2 / TUIC (QUIC) - کانفیگ نمونه برای کلاینت Hiddify
  const hyLinks = [
    `hysteria2://${uuid}@${rand(ARVAN_CLEAN_IPS)}:443?insecure=1&sni=${rand(WHITELIST_SNI)}#${encodeURIComponent("[HY2-QUIC] Arvan")}`,
    `tuic://${uuid}:${uuid}@${rand(CF_CLEAN_IPS)}:443?congestion_control=bbr&udp_relay_mode=native&alpn=h3&sni=${domain}#${encodeURIComponent("[TUIC] CF")}`
  ];
  return { vless: all, ss: ssLinks, hy: hyLinks };
}
function toClashYAML(domain, uuid){
  const {vless} = generatePhantomConfigs(domain, uuid);
  let y = "proxies:\n";
  vless.forEach((c,i)=>{
    y += `  - name: "${c.tier}-${i+1}"\n    type: vless\n    server: ${c.ip}\n    port: ${c.port}\n    uuid: ${uuid}\n    tls: true\n    servername: ${c.sni}\n    fingerprint: ${c.fp}\n    network: ${c.type==="grpc"?"grpc":"ws"}\n    ws-opts:\n      path: "${decodeURIComponent(c.link.split("path=")[1].split("&")[0])}"\n      headers:\n        Host: ${domain}\n    fragmentation:\n      enabled: true\n      length: ${c.frag.len}\n      interval: ${c.frag.interval}\n`;
  });
  y += "\nproxy-groups:\n  - name: OMNI-PHANTOM\n    type: url-test\n    proxies: [" + vless.map((_,i)=>`"${vless[i].tier}-${i+1}"`).join(", ") + "]\n    url: https://www.gstatic.com/generate_204\n    interval: 30\n";
  return y;
}
function toSingBoxJSON(domain, uuid){
  const {vless, ss, hy} = generatePhantomConfigs(domain, uuid);
  const outbounds = vless.map((c,i)=>({
    type:"vless", tag:`${c.tier}-${i+1}`, server:c.ip, server_port:c.port,
    uuid: uuid, tls:{ enabled:true, server_name:c.sni, insecure:true, utls:{ enabled:true, fingerprint:c.fp } },
    transport:{ type:c.type, path: decodeURIComponent(c.link.split("path=")[1].split("&")[0]), headers:{ Host: domain } },
    multiplex:{ enabled:true, max_streams:8 }
  }));
  // اضافه SS2022
  ss.forEach((s,i)=> outbounds.push({ type:"shadowsocks", tag:`SS2022-${i+1}`, server: s.split("@")[1].split(":")[0], server_port:443, method:"2022-blake3-aes-128-gcm", password: s.split(":")[1].split("@")[0] }));
  return JSON.stringify({ outbounds, route:{ auto_detect_interface:true }, experimental:{ cache_file:{ enabled:true } } }, null, 2);
}

