// (v10) Fake probe simulators removed. Ranking uses ONLY real RUM reports now.
async function personalizedRanking(env, asn="AS197207", city="Tehran", opts={}){
  // v10 REAL RANKING: scores ONLY from real client reports (/api/rum/collect).
  // Unmeasured IPs are clearly marked NO-DATA (never fake numbers).
  let operator = opts.operator || "MCI";
  for(const [k,v] of Object.entries(OPERATOR_PROFILES)) if(v.asn===asn) operator = k;
  city = CITY_POPS[city] ? city : "Tehran";
  const pool = [...ARVAN_ULTRA_POOL, ...CF_ULTRA_POOL, ...WARP_IPS];
  const kv = env.SESSIONS_KV || env.KV;
  const now = Date.now();
  const rows = await Promise.all(pool.map(ip => (async()=>{
    let g=null, seg=null;
    if(kv) try{ const v=await kv.get(`rum:g:${ip}`); if(v) g=JSON.parse(v); }catch{}
    if(kv) try{ const v=await kv.get(`rum:${OPERATOR_PROFILES[operator].asn}:${city}:${ip}`); if(v) seg=JSON.parse(v); }catch{}
    return {ip, g, seg};
  })()));
  const ranked = rows.map(({ip, g, seg})=>{
    const isArvan = ip.startsWith("185")||ip.startsWith("37.")||ip.startsWith("94.");
    const isWarp = ip.startsWith("188.114")||ip.startsWith("162.159.19");
    const sni = isArvan ? ULTRA_SNI_STRATEGY.ultra_stealth[ip.split(".").reduce((a,b)=>a+(+b),0)%ULTRA_SNI_STRATEGY.ultra_stealth.length]
      : (isWarp ? "cloudflare.com" : (opts.domain||"worker"));
    const port = isArvan ? (OPERATOR_PROFILES[operator].ports[0]||443) : 443;
    const lat = (g&&g.t!=null) ? g.t : ((seg&&seg.t!=null) ? seg.t : null);
    const loss = (g&&g.loss!=null) ? g.loss : ((seg&&seg.loss!=null) ? seg.loss : null);
    const ts = Math.max((g&&g.ts)||0, (seg&&seg.ts)||0);
    const ageH = ts ? (now-ts)/3600000 : 999;
    const measured = (lat!=null) && (ageH<24);
    let score, status;
    if(measured){
      score = lat*0.5 + (loss||0)*25 + ageH*2;
      const segDead = (!g && seg && seg.ok===0);
      status = ((loss>5)||segDead) ? "🔴 RISKY" : (((loss>1)||(lat>150)) ? "🟡 DEGRADED" : "🟢 VERIFIED");
    } else {
      const j = ip.split(".").reduce((a,b)=>a+(+b),0)%50;
      score = 400 + j; // unmeasured sorts after measured
      status = "⚪ NO-DATA";
    }
    return { ip, port, sni, latency: lat, loss, measured, reports: (g&&g.n)||0,
      age_h: ts?Math.round(ageH*10)/10:null, score: Math.round(score*10)/10,
      asn: OPERATOR_PROFILES[operator].asn, city, operator, status,
      fragment: `${10+(ip.charCodeAt(0)%20)}-${40+(ip.charCodeAt(2)%40)}`, fp: UTLS_FPS[ip.charCodeAt(1)%UTLS_FPS.length] };
  });
  ranked.sort((a,b)=> a.score-b.score);
  return ranked.slice(0, 12);
}
function chunkStr(s, n){ const out=[]; for(let i=0;i<s.length;i+=n) out.push(s.slice(i,i+n)); return out; }

async function cfUpsertTxt(env, zoneId, name, value){
  const tok = env.CF_API_TOKEN || env.CF_TOKEN || "";
  if(!tok || !zoneId) return false;
  try{
    const H = { "Authorization":"Bearer "+tok, "Content-Type":"application/json" };
    const list = await (await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneId}/dns_records?type=TXT&name=${name}`,{headers:H})).json();
    const body = JSON.stringify({ type:"TXT", name, content:value, ttl:60 });
    if(list.success && list.result && list.result.length){
      const u = await (await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneId}/dns_records/${list.result[0].id}`,{method:"PUT",headers:H,body})).json();
      return !!u.success;
    }
    const c = await (await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneId}/dns_records`,{method:"POST",headers:H,body})).json();
    return !!c.success;
  }catch{ return false; }
}
async function arvanUpsertTxt(env, domain, name, value){
  const key = env.ARVAN_API_KEY || "";
  if(!key) return false;
  try{
    const H = { "Authorization": key, "Content-Type":"application/json" };
    const list = await (await fetch(`https://napi.arvancloud.ir/cdn/4.0/domains/${domain}/dns-records?search=${name}`,{headers:H})).json();
    const recs = (list && list.data) || [];
    const found = recs.find(r=>r.name===name && String(r.type).toLowerCase()==="txt");
    if(found){
      const u = await fetch(`https://napi.arvancloud.ir/cdn/4.0/domains/${domain}/dns-records/${found.id}`,{method:"PUT",headers:H,body:JSON.stringify({value, ttl:30})});
      return u.ok;
    }
    const c = await fetch(`https://napi.arvancloud.ir/cdn/4.0/domains/${domain}/dns-records`,{method:"POST",headers:H,body:JSON.stringify({type:"txt",name,value,ttl:30})});
    return c.ok;
  }catch{ return false; }
}

// ============ WHITEHOLE DEAD-DROP v10 (real) ============
// Publishes fallback IPs + sub link as DNS TXT shards so clients inside Iran can
// fetch them with domestic resolvers during a shutdown:
//   dig +short TXT ghost1.<domain> @178.22.122.100
// REQUIREMENT: <domain> DNS must stay resolvable inside Iran during shutdown →
// use a .ir domain on domestic nameservers (e.g. ArvanCloud DNS).
async function whiteHolePublish(env, domain, opts={}){
  const ranked = await personalizedRanking(env, opts.asn||"AS197207", opts.city||"Tehran", opts);
  const host = opts.workerHost || "";
  const ordered = ranked.filter(r=>r.measured).concat(ranked.filter(r=>!r.measured)).slice(0,10);
  const payload = {
    v: 10, ts: Date.now(), domain,
    ips: ordered.map(r=>({ip:r.ip, port:r.port, sni:r.sni, st:r.status})),
    dns: DOMESTIC_DNS_ULTRA.slice(0,4),
    sni: ULTRA_SNI_STRATEGY.ultra_stealth.slice(0,5),
    sub: host ? `https://${host}/api/phantom?domain=${domain}&format=v2ray` : ""
  };
  const json = JSON.stringify(payload);
  const b64 = btoa(unescape(encodeURIComponent(json)));
  const parts = chunkStr(b64, 180);
  const checksum = b64.length % 97;
  const kv = env.SESSIONS_KV || env.KV;
  if(kv) try{
    await kv.put(`ghost:${domain}`, json, { expirationTtl: 21600 });
    await kv.put(`ghost:${domain}:b64`, b64, { expirationTtl: 21600 });
    for(let i=0;i<parts.length;i++) await kv.put(`ghost_txt:${domain}:${i+1}`, parts[i], { expirationTtl: 21600 });
    await kv.put(`ghost_meta:${domain}`, JSON.stringify({v:10, count:parts.length, len:b64.length, checksum, ts:Date.now()}), { expirationTtl: 21600 });
  }catch{}
  if(env.GHOST_BUCKET) try{ await env.GHOST_BUCKET.put(`ghost-${domain}.json`, json); }catch{}
  let dnsOk = 0;
  for(let i=0;i<Math.min(parts.length,8);i++){
    const fname = `ghost${i+1}`;
    const fval = `v10;p${i+1}=${parts[i]};n=${parts.length};c=${checksum}`;
    let ok = await arvanUpsertTxt(env, domain, fname, fval);
    if(!ok && env.CF_ZONE_ID) ok = await cfUpsertTxt(env, env.CF_ZONE_ID, `${fname}.${domain}`, fval);
    if(ok) dnsOk++;
  }
  return { ok:true, domain, shards:parts.length, dnsPublished:dnsOk, measured: ranked.filter(r=>r.measured).length, ts:Date.now() };
}
// legacy alias
async function whiteHoleWriter(env, domain, ips, dnsList){ return whiteHolePublish(env, domain, {}); }
