// ========== Auth guard (v10) ==========
function isAuthed(req, env){
  try{
    const c = req.headers.get("Cookie")||"";
    if(c.indexOf("omni_auth=1")>=0) return true;
    const a = req.headers.get("Authorization")||"";
    const pass = String(env.PASSWORD||env.ADMIN_PASSWORD||DEFAULT_PASSWORD||"").trim();
    if(pass && a==="Bearer "+pass) return true;
  }catch{}
  return false;
}
function needAuth(){ return new Response(JSON.stringify({error:"unauthorized"}),{status:401,headers:{"Content-Type":"application/json"}}); }

