async function getUsers(env){
  if(env.SESSIONS_KV) try{ const v=await env.SESSIONS_KV.get("omni_pro_users"); if(v) return JSON.parse(v); }catch{}
  if(env.KV) try{ const v=await env.KV.get("omni_pro_users"); if(v) return JSON.parse(v); }catch{}
  return [];
}
async function saveUsers(env, users){
  const val=JSON.stringify(users);
  // فقط KV (بدون دیتابیس D1 — عمداً حذف شد تا ورکر هیچ بایند دیتابیسی لازم نداشته باشه)
  if(env.SESSIONS_KV) try{ await env.SESSIONS_KV.put("omni_pro_users", val); }catch{}
  if(env.KV) try{ await env.KV.put("omni_pro_users", val); }catch{}
}
async function handleLogin(req, env){
  try{
    const b = await req.json();
    const pass = env.PASSWORD || DEFAULT_PASSWORD;
    if(b.pass === pass){
      return new Response(JSON.stringify({ok:true}),{
        headers:{"Content-Type":"application/json", "Set-Cookie":"omni_auth=1; Path=/; HttpOnly; Max-Age=86400; SameSite=Lax"}
      });
    }
    return new Response(JSON.stringify({ok:false, error:"رمز اشتباه است"}),{status:401, headers:{"Content-Type":"application/json"}});
  }catch{ return new Response(JSON.stringify({ok:false}),{status:400}); }
}

async function getAllowedUUIDs(env){
  const s = new Set();
  const main = String(env.UUID || DEFAULT_UUID || "").toLowerCase();
  if(main) s.add(main);
  try{ const us = await getUsers(env); for(const u of us){ if(u && u.uuid) s.add(String(u.uuid).toLowerCase()); } }catch{}
  return s;
}
function vlessUUIDFrom(buf){
  try{
    const b = Array.from(new Uint8Array(buf.slice(1,17)));
    const h = b.map(x=>x.toString(16).padStart(2,"0")).join("");
    return (h.slice(0,8)+"-"+h.slice(8,12)+"-"+h.slice(12,16)+"-"+h.slice(16,20)+"-"+h.slice(20)).toLowerCase();
  }catch{ return ""; }
}
async function handleVless(req, env){
  const allowed = await getAllowedUUIDs(env);
  const pair=new WebSocketPair(); const [client, server]=Object.values(pair); server.accept();
  let remote=null;
  server.addEventListener("message", async e=>{
    try{
      const buf=e.data; if(!(buf instanceof ArrayBuffer)) return;
      if(!remote){
        if(buf.byteLength<24) return;
        const v=new DataView(buf); if(v.getUint8(0)!==0) return;
        if(!allowed.has(vlessUUIDFrom(buf))){ try{server.close(4401, "unauthorized");}catch{} return; } // 🔒 UUID auth (v10)
        const opt=v.getUint8(17), cmd=v.getUint8(18+opt); if(cmd!==1) return;
        const port=v.getUint16(19+opt), type=v.getUint8(21+opt);
        let addr="", idx=22+opt, len=0;
        if(type===1){ addr=new Uint8Array(buf.slice(idx,idx+4)).join("."); len=4; }
        else if(type===2){ len=v.getUint8(idx); idx+=1; addr=new TextDecoder().decode(buf.slice(idx,idx+len)); }
        else if(type===3){ const dv=new DataView(buf.slice(idx,idx+16)); const p=[]; for(let i=0;i<8;i++) p.push(dv.getUint16(i*2).toString(16)); addr=p.join(":"); len=16; }
        const hdrLen=idx+len; const data=buf.slice(hdrLen);
        let host=addr; if(host.includes("cloudflare")||host.includes("workers.dev")) host="cdn-all.xn--b6gac.eu.org";
        try{
          remote=connect({hostname:host, port}); const w=remote.writable.getWriter(); await w.write(data); w.releaseLock();
          server.send(new Uint8Array([0,0]));
          remote.readable.pipeTo(new WritableStream({write(c){ server.send(c); }, close(){ server.close(); }})).catch(()=>{});
        }catch{ server.close(); }
      }else{ const w=remote.writable.getWriter(); await w.write(buf); w.releaseLock(); }
    }catch{ server.close(); }
  });
  return new Response(null,{status:101, webSocket:client});
}


