// ═══════════════════════════════════════════════════════════════════
// HAMZAD PACK — ادغام‌شده در OMNI-ROUTER (v12)
// این سه ماژول بدون تغییر منطق از پکِ همزاد کپی شدن.
// نیاز به این envها داره (Settings → Variables روی همین ورکر):
//   DGA_SECRET, DGA_ZONE
//   HY2_ADDR, HY2_PASS, HY2_NAME, HY2_UP, HY2_DOWN
//   VLESS_HOST, VLESS_PORT, VLESS_UUID, VLESS_NAME, REALITY_PUB, REALITY_SHORT
//   WG_PRIV, WG_PUB, WG_IP
//   DNSTT_NS (اختیاری), PROFILE_SECRET (اختیاری، پیش‌فرض PASSWORD)
// بایند جدید لازم نیست؛ از همون SESSIONS_KV موجود استفاده می‌کنه.
// ═══════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
// HAMZAD · DGA TIME RENDEZVOUS (ماژول ورکر)
// WHERE: کل این فایل روverbatim توی worker.js بچسبون (سطح top-level).
//        بعد بلاک ROUTE پایین رو اولِ ()fetch بذار (قبل از همه routeها).
// NEEDS env: DGA_SECRET (رشته تصادفی بلند، مشترک بین تو و کلاینت)
//           DGA_ZONE   (مثلا "example.com")
// DNS: رکورد wildcard روی زون: *.DGA_ZONE → پروکسی به همین ورکر
// منطق: کلاینت دامنه امروز رو آفلاین حساب می‌کنه؛ چیزی توزیع نمی‌شه که بلاک بشه.
// ═══════════════════════════════════════════════════════════════════
//
// --- ROUTE (اول fetch، فرض: req, env, u=new URL(req.url) موجودن):
// const __dga = await dgaCheck(u.hostname, env);
// if(__dga && u.pathname==="/cfg") return cfgResponse(u, env);
// // (اختیاری) مخفی نگه داشتن ساب فقط پشت DGA:
// // if(u.pathname==="/sub" && env.SUB_DGA_ONLY==="1" && !__dga)
// //   return new Response("not found",{status:404});
//
// --- derive سمت کلاینت:
//   JS (مرورگر): همین دو تابع hmacHex و dayStr رو کپی کن:
//     const label=(await hmacHex(DGA_SECRET, dayStr(0))).slice(0,12);
//     const host=label+"."+DGA_ZONE;
//   Python:
//     import hmac,hashlib,datetime
//     d=datetime.datetime.utcnow().strftime('%Y%m%d')
//     label=hmac.new(SECRET.encode(),d.encode(),hashlib.sha256).hexdigest()[:12]
//     host=label+"."+ZONE
//   Shell:
//     L=$(date -u +%Y%m%d | openssl dgst -sha256 -hmac "$SECRET" | cut -c1-12)
//     echo "$L.$ZONE"
// ═══════════════════════════════════════════════════════════════════

async function hmacHex(keyStr, msgStr){
  const km = await crypto.subtle.importKey("raw", new TextEncoder().encode(keyStr),
    {name:"HMAC", hash:"SHA-256"}, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", km, new TextEncoder().encode(msgStr));
  return [...new Uint8Array(sig)].map(b=>b.toString(16).padStart(2,"0")).join("");
}
function constEq(a,b){
  if(a.length!==b.length) return false;
  let d=0; for(let i=0;i<a.length;i++) d |= a.charCodeAt(i)^b.charCodeAt(i);
  return d===0;
}
function dayStr(offsetDays){
  const d = new Date(Date.now()+(offsetDays||0)*864e5);
  return d.toISOString().slice(0,10).replaceAll("-",""); // UTC YYYYMMDD
}
async function dgaLabels(env){
  const out=[];
  for(const o of [-1,0,1]) out.push((await hmacHex(env.DGA_SECRET, dayStr(o))).slice(0,12));
  return out; // پنجره ۳روزه برای اختلاف timezone/skew
}
async function dgaCheck(host, env){
  host=(host||"").toLowerCase();
  if(!env.DGA_SECRET || !env.DGA_ZONE) return false;
  const zone=env.DGA_ZONE.toLowerCase();
  if(!host.endsWith("."+zone)) return false;
  const label=host.slice(0, host.length-zone.length-1);
  if(!label || label.includes(".")) return false; // فقط تک‌لیبل
  const ls=await dgaLabels(env);
  for(const l of ls) if(constEq(label,l)) return true;
  return false;
}
// پاسخ rendezvous: همه endpointها روی همین هاستِ امروز (پس همه‌چی پشت DGA می‌مونه)
function cfgResponse(u, env){
  const origin="https://"+u.hostname;
  const midnight=new Date(); midnight.setUTCHours(24,0,0,0);
  return new Response(JSON.stringify({
    v:1, now:new Date().toISOString(), valid_until:midnight.toISOString(),
    endpoints:{ profile:origin+"/profile", sub:origin+"/sub",
      sensor:origin+"/map/sensor", live:origin+"/map/live" }
  }),{headers:{"Content-Type":"application/json","Cache-Control":"no-store"}});
}

// ═══════════════════════════════════════════════════════════════════
// HAMZAD · LIVE CENSORSHIP MAP (ماژول ورکر)
// WHERE: کل فایل top-level؛ بلاک ROUTE رو داخل ()fetch بذار (بعد از DGA).
// NEEDS env: SESSIONS_KV (همون بایندینگ موجود — بایند جدید لازم نیست)
//           MAP_SECRET لازم نیست؛ ضداسپم با rate-limit و میانه‌گیریه.
// حریم خصوصی: هیچ IP یا شناسه کاربری ذخیره نمی‌شه — فقط aggregate.
// Routes:
//   POST /map/report   دریافت گزارش سنسور {isp,city,rtt,ok,tr}
//   GET  /map/ping     تارگت کوچیک برای اندازه‌گیری RTT
//   GET  /map/sensor   صفحه سنسور گوشی‌محور (انتخاب ISP/شهر + دکمه تست)
//   GET  /map/live    خروجی JSON تجمیعی
//   GET  /map         داشبورد فارسی موبایل‌فرندلی (auto-refresh)
// تابع mapTransportHealth(env) خوراک موتور استراتژیه (worker-strategy.js).
// ═══════════════════════════════════════════════════════════════════
//
// --- ROUTE:
// if(u.pathname==="/map/report"&&req.method==="POST") return mapReport(req,env);
// if(u.pathname==="/map/ping") return new Response('{"p":1}',{headers:{"Content-Type":"application/json","Cache-Control":"no-store"}});
// if(u.pathname==="/map/sensor") return mapSensorPage();
// if(u.pathname==="/map/live") return mapLive(env);
// if(u.pathname==="/map") return mapDashboard(env);
// ═══════════════════════════════════════════════════════════════════

const HZ_ISPS=["همراه‌اول","ایرانسل","رایتل","مخابرات","شاتل","های‌وب","آسیاتک","مبین‌نت","زیتل","پارس‌آنلاین","سایر"];
const HZ_TRS=["hysteria2","vless-reality","ech","fragment","dns","other"];
function hzBucket(k){ // باکت ساعتی UTC: YYYYMMDDHH
  return new Date(Date.now()-k*36e5).toISOString().slice(0,13).replace(/[-T]/g,"");
}
function hzMedian(a){
  if(!a.length) return -1;
  const s=[...a].sort((x,y)=>x-y);
  return s[Math.floor(s.length/2)];
}
function hzCleanCity(c){
  c=String(c||"تهران").slice(0,40);
  return c.replace(/[<>&"']/g,"").trim()||"تهران";
}
async function mapReport(req, env){
  const ip=req.headers.get("cf-connecting-ip")||"0";
  try{
    // ضداسپم: ۳۰ گزارش/ساعت برای هر IP
    const rk="rl:"+ip;
    const n=parseInt(await env.SESSIONS_KV.get(rk)||"0",10);
    if(n>=30) return new Response(JSON.stringify({error:"rate limited"}),{status:429});
    await env.SESSIONS_KV.put(rk, String(n+1), {expirationTtl:3600});
    const b=await req.json();
    const isp=HZ_ISPS.includes(b.isp)?b.isp:"سایر";
    const city=hzCleanCity(b.city);
    const rtt=(typeof b.rtt==="number"&&b.rtt>=-1&&b.rtt<=10000)?Math.round(b.rtt):-1;
    const ok=b.ok===1?1:0;
    const tr=HZ_TRS.includes(b.tr)?b.tr:"other";
    const key="map:"+hzBucket(0)+":"+crypto.randomUUID();
    await env.SESSIONS_KV.put(key, JSON.stringify({isp,city,rtt,ok,tr,t:Date.now()}), {expirationTtl:172800});
    return new Response(JSON.stringify({saved:1}),{headers:{"Content-Type":"application/json"}});
  }catch(e){
    return new Response(JSON.stringify({error:"bad report"}),{status:400});
  }
}
async function mapAggregate(env){
  const cells={}, trs={}; // key: isp|c city
  for(let k=0;k<3;k++){
    const pre="map:"+hzBucket(k)+":";
    let cur=null;
    for(let pg=0;pg<10;pg++){ // حداکثر ۱۰ صفحه برای MVP
      const l=await env.SESSIONS_KV.list({prefix:pre, cursor:cur||undefined, limit:200});
      for(const key of l.keys){
        try{
          const r=await env.SESSIONS_KV.get(key.name,{type:"json"});
          if(!r) continue;
          const ck=r.isp+"|"+r.city;
          (cells[ck]=cells[ck]||{isp:r.isp,city:r.city,n:0,ok:0,rtts:[],trs:{}});
          const c=cells[ck]; c.n++; c.ok+=r.ok; if(r.rtt>=0) c.rtts.push(r.rtt);
          (c.trs[r.tr]=c.trs[r.tr]||{n:0,ok:0}); c.trs[r.tr].n++; c.trs[r.tr].ok+=r.ok;
          (trs[r.tr]=trs[r.tr]||{n:0,ok:0}); trs[r.tr].n++; trs[r.tr].ok+=r.ok;
        }catch(e){}
      }
      if(l.list_complete) break; cur=l.cursor;
    }
  }
  const out=[];
  for(const k in cells){
    const c=cells[k], rate=c.n?c.ok/c.n:0;
    out.push({isp:c.isp, city:c.city, n:c.n, okRate:Math.round(rate*100)/100,
      rtt:hzMedian(c.rtts),
      verdict: c.n<3?"nodata": rate>=0.8?"up": rate>=0.4?"degraded":"down"});
  }
  out.sort((a,b)=>a.okRate-b.okRate); // خراب‌ها بالا (ops-first)
  const trOut={};
  for(const t in trs) trOut[t]={n:trs[t].n, okRate:Math.round(trs[t].ok/trs[t].n*100)/100};
  return {updated:new Date().toISOString(), cells:out, transports:trOut};
}
async function mapTransportHealth(env){ // خوراک موتور استراتژی
  try{ return (await mapAggregate(env)).transports; }catch(e){ return {}; }
}
async function mapLive(env){
  return new Response(JSON.stringify(await mapAggregate(env)),
    {headers:{"Content-Type":"application/json","Cache-Control":"no-store"}});
}
const HZ_V={up:["🟢","سالم"],degraded:["🟡","اختلال"],down:["🔴","قطع"],nodata:["⚪","کم‌دیتا"]};
function faNum(n){ try{return Number(n).toLocaleString("fa-IR");}catch(e){return String(n);} }
async function mapDashboard(env){
  const a=await mapAggregate(env);
  let rows="";
  for(const c of a.cells){
    const v=HZ_V[c.verdict]||HZ_V.nodata;
    rows+='<div class="card '+c.verdict+'"><div class="t">'+v[0]+' '+c.city+' — '+c.isp+'</div>'
      +'<div class="s">'+v[1]+' · سلامت '+faNum(Math.round(c.okRate*100))+'٪ · میانه پینگ '+(c.rtt>=0?faNum(c.rtt)+'ms':'—')+' · '+faNum(c.n)+' گزارش</div></div>';
  }
  if(!rows) rows='<div class="card nodata"><div class="s">هنوز گزارشی نرسیده — از /map/sensor تست بفرست.</div></div>';
  let trs="";
  for(const t in a.transports) trs+="<tr><td>"+t+"</td><td>"+faNum(Math.round(a.transports[t].okRate*100))+"٪</td><td>"+faNum(a.transports[t].n)+"</td></tr>";
  const html='<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8">'
    +'<meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="120">'
    +'<title>نقشه زنده سانسور</title><style>'
    +'body{font-family:system-ui,Tahoma;background:#0e1116;color:#e6e6e6;margin:0;padding:14px}'
    +'h2{margin:4px 0 2px}.u{color:#888;font-size:12px;margin-bottom:10px}'
    +'.card{background:#161b22;border-radius:10px;padding:10px 12px;margin:8px 0;border-right:5px solid #666}'
    +'.up{border-color:#2ea043}.degraded{border-color:#d29922}.down{border-color:#f85149}.nodata{border-color:#666}'
    +'.t{font-weight:700}.s{font-size:13px;color:#aaa;margin-top:3px}'
    +'table{width:100%;font-size:13px;border-collapse:collapse;margin-top:10px}'
    +'td{border-top:1px solid #333;padding:6px 4px}</style></head><body>'
    +'<h2>🗺 نقشه زنده سانسور</h2><div class="u">به‌روز شده: '+a.updated+'</div>'
    +rows+'<h3>وضعیت ترانسپورت‌ها (سراسری)</h3><table>'+trs+'</table></body></html>';
  return new Response(html,{headers:{"Content-Type":"text/html;charset=utf-8","Cache-Control":"no-store"}});
}
