      if(!payload && env.GHOST_BUCKET) try{ const o=await env.GHOST_BUCKET.get(`ghost-${domain}.json`); if(o) payload=await o.text(); }catch{}
      if(!payload) payload = JSON.stringify({ domain, ips: ARVAN_CLEAN_IPS.slice(0,5).map(ip=>`${ip}:443`), status: "active" });
      return new Response(payload,{headers:{"Content-Type":"application/json","Access-Control-Allow-Origin":"*"}});
